-- ============================================================
-- HayPOS Supabase Schema (Clean & Safe Setup)
-- ============================================================

-- 1. Extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. Drop existing tables if re-running (avoids "relation already exists" error)
DROP TABLE IF EXISTS store_settings CASCADE;
DROP TABLE IF EXISTS stock_movements CASCADE;
DROP TABLE IF EXISTS promotions CASCADE;
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS order_items CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS profiles CASCADE;
DROP TABLE IF EXISTS stores CASCADE;

-- 3. Drop existing functions
DROP FUNCTION IF EXISTS update_updated_at_column() CASCADE;
DROP FUNCTION IF EXISTS get_my_store_id() CASCADE;
DROP FUNCTION IF EXISTS get_my_role() CASCADE;
DROP FUNCTION IF EXISTS create_order_transaction(UUID, UUID, TEXT, NUMERIC, NUMERIC, NUMERIC, NUMERIC, TEXT, TEXT, UUID, JSONB) CASCADE;

CREATE TABLE stores (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name TEXT NOT NULL,
    logo_url TEXT,
    tagline TEXT,
    phone TEXT,
    address TEXT,
    currency TEXT DEFAULT 'THB',
    timezone TEXT DEFAULT 'Asia/Bangkok',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE UNIQUE NOT NULL,
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    full_name TEXT NOT NULL,
    email TEXT,
    role TEXT NOT NULL DEFAULT 'staff' CHECK (role IN ('owner','admin','staff')),
    avatar_url TEXT,
    status TEXT DEFAULT 'active' CHECK (status IN ('active','inactive')),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID REFERENCES stores(id) ON DELETE CASCADE NOT NULL,
    name TEXT NOT NULL,
    emoji TEXT,
    color TEXT,
    sort_order INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE products (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID NOT NULL,
    category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
    sku TEXT,
    name TEXT NOT NULL,
    flavor TEXT,
    emoji TEXT DEFAULT '🍰',
    price NUMERIC(10,2) NOT NULL DEFAULT 0,
    stock INT NOT NULL DEFAULT 0,
    status TEXT DEFAULT 'active' CHECK (status IN ('active','inactive','out_of_stock')),
    image_url TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE customers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID NOT NULL,
    name TEXT NOT NULL,
    email TEXT,
    phone TEXT,
    address TEXT,
    tag TEXT DEFAULT 'New' CHECK (tag IN ('VIP','Regular','New')),
    notes TEXT,
    total_orders INT DEFAULT 0,
    total_spending NUMERIC(12,2) DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE orders (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID NOT NULL,
    customer_id UUID REFERENCES customers(id) ON DELETE SET NULL,
    order_number TEXT NOT NULL,
    subtotal NUMERIC(12,2) NOT NULL DEFAULT 0,
    discount NUMERIC(12,2) DEFAULT 0,
    tax NUMERIC(12,2) DEFAULT 0,
    total NUMERIC(12,2) NOT NULL DEFAULT 0,
    payment_method TEXT DEFAULT 'cash' CHECK (payment_method IN ('cash','qr','card')),
    payment_status TEXT DEFAULT 'pending' CHECK (payment_status IN ('pending','paid','refunded')),
    status TEXT DEFAULT 'waiting' CHECK (status IN ('waiting','verify','preparing','completed','cancelled')),
    note TEXT,
    created_by UUID REFERENCES auth.users(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE order_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id UUID REFERENCES orders(id) ON DELETE CASCADE NOT NULL,
    product_id UUID REFERENCES products(id) ON DELETE SET NULL,
    product_name TEXT NOT NULL,
    quantity INT NOT NULL DEFAULT 1,
    unit_price NUMERIC(10,2) NOT NULL,
    total NUMERIC(12,2) NOT NULL
);

CREATE TABLE reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID NOT NULL,
    customer_id UUID REFERENCES customers(id) ON DELETE SET NULL,
    order_id UUID REFERENCES orders(id) ON DELETE SET NULL,
    customer_name TEXT NOT NULL,
    rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment TEXT,
    reply TEXT,
    is_pinned BOOLEAN DEFAULT FALSE,
    is_hidden BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE promotions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID NOT NULL,
    code TEXT NOT NULL,
    type TEXT DEFAULT 'percent' CHECK (type IN ('percent','fixed')),
    discount NUMERIC(10,2) NOT NULL DEFAULT 0,
    min_order NUMERIC(10,2) DEFAULT 0,
    max_uses INT DEFAULT NULL,
    used_count INT DEFAULT 0,
    start_date DATE,
    end_date DATE,
    status TEXT DEFAULT 'active' CHECK (status IN ('active','inactive','expired')),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE stock_movements (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID NOT NULL,
    product_id UUID REFERENCES products(id) ON DELETE CASCADE NOT NULL,
    type TEXT NOT NULL CHECK (type IN ('in','out','adjustment')),
    quantity INT NOT NULL,
    reference_id UUID,
    reference_type TEXT,
    note TEXT,
    created_by UUID REFERENCES auth.users(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE store_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id UUID REFERENCES stores(id) ON DELETE CASCADE UNIQUE NOT NULL,
    tax_rate NUMERIC(5,2) DEFAULT 7,
    qr_image_url TEXT,
    bank_name TEXT,
    bank_account TEXT,
    account_holder TEXT,
    primary_color TEXT DEFAULT '#F8BFD4',
    dark_mode BOOLEAN DEFAULT false,
    theme_config JSONB,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Foreign Keys
ALTER TABLE products ADD FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE;
ALTER TABLE customers ADD FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE;
ALTER TABLE orders ADD FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE;
ALTER TABLE reviews ADD FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE;
ALTER TABLE promotions ADD FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE;
ALTER TABLE stock_movements ADD FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE;

-- Indexes
CREATE INDEX ON products(store_id);
CREATE INDEX ON products(category_id);
CREATE INDEX ON products(status);
CREATE INDEX ON orders(store_id);
CREATE INDEX ON orders(status);
CREATE INDEX ON orders(created_at);
CREATE INDEX ON orders(customer_id);
CREATE INDEX ON customers(store_id);
CREATE INDEX ON stock_movements(store_id);
CREATE INDEX ON stock_movements(product_id);
CREATE INDEX ON reviews(store_id);
CREATE INDEX ON promotions(store_id);
CREATE INDEX ON promotions(code);
CREATE INDEX ON order_items(order_id);
CREATE INDEX ON order_items(product_id);

-- Updated_at trigger function
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_stores_updated_at BEFORE UPDATE ON stores FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER update_products_updated_at BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER update_customers_updated_at BEFORE UPDATE ON customers FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER update_orders_updated_at BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- Helper RLS functions
CREATE OR REPLACE FUNCTION get_my_store_id()
RETURNS UUID LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT store_id FROM profiles WHERE user_id = auth.uid() LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION get_my_role()
RETURNS TEXT LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT role FROM profiles WHERE user_id = auth.uid() LIMIT 1;
$$;

-- Grant public and authenticated access to tables
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO anon, authenticated, service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON ROUTINES TO anon, authenticated, service_role;

-- RLS Policies
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "profiles_select" ON profiles FOR SELECT USING (user_id = auth.uid() OR get_my_role() IN ('owner','admin'));
CREATE POLICY "profiles_insert" ON profiles FOR INSERT WITH CHECK (user_id = auth.uid());
CREATE POLICY "profiles_update" ON profiles FOR UPDATE USING (user_id = auth.uid());

ALTER TABLE stores ENABLE ROW LEVEL SECURITY;
CREATE POLICY "stores_select" ON stores FOR SELECT USING (true);
CREATE POLICY "stores_update" ON stores FOR UPDATE USING (true);

ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "cat_sel" ON categories FOR SELECT USING (true);
CREATE POLICY "cat_ins" ON categories FOR INSERT WITH CHECK (true);
CREATE POLICY "cat_upd" ON categories FOR UPDATE USING (true);
CREATE POLICY "cat_del" ON categories FOR DELETE USING (true);

ALTER TABLE products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "prod_sel" ON products FOR SELECT USING (true);
CREATE POLICY "prod_ins" ON products FOR INSERT WITH CHECK (true);
CREATE POLICY "prod_upd" ON products FOR UPDATE USING (true);
CREATE POLICY "prod_del" ON products FOR DELETE USING (true);

ALTER TABLE customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "cust_sel" ON customers FOR SELECT USING (true);
CREATE POLICY "cust_ins" ON customers FOR INSERT WITH CHECK (true);
CREATE POLICY "cust_upd" ON customers FOR UPDATE USING (true);
CREATE POLICY "cust_del" ON customers FOR DELETE USING (true);

ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "ord_sel" ON orders FOR SELECT USING (true);
CREATE POLICY "ord_ins" ON orders FOR INSERT WITH CHECK (true);
CREATE POLICY "ord_upd" ON orders FOR UPDATE USING (true);
CREATE POLICY "ord_del" ON orders FOR DELETE USING (true);

ALTER TABLE order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "oi_sel" ON order_items FOR SELECT USING (true);
CREATE POLICY "oi_ins" ON order_items FOR INSERT WITH CHECK (true);
CREATE POLICY "oi_upd" ON order_items FOR UPDATE USING (true);
CREATE POLICY "oi_del" ON order_items FOR DELETE USING (true);

ALTER TABLE reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "rev_sel" ON reviews FOR SELECT USING (true);
CREATE POLICY "rev_ins" ON reviews FOR INSERT WITH CHECK (true);
CREATE POLICY "rev_upd" ON reviews FOR UPDATE USING (true);
CREATE POLICY "rev_del" ON reviews FOR DELETE USING (true);

ALTER TABLE promotions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "promo_sel" ON promotions FOR SELECT USING (true);
CREATE POLICY "promo_ins" ON promotions FOR INSERT WITH CHECK (true);
CREATE POLICY "promo_upd" ON promotions FOR UPDATE USING (true);
CREATE POLICY "promo_del" ON promotions FOR DELETE USING (true);

ALTER TABLE stock_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "sm_sel" ON stock_movements FOR SELECT USING (true);
CREATE POLICY "sm_ins" ON stock_movements FOR INSERT WITH CHECK (true);
CREATE POLICY "sm_upd" ON stock_movements FOR UPDATE USING (true);
CREATE POLICY "sm_del" ON stock_movements FOR DELETE USING (true);

ALTER TABLE store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "set_sel" ON store_settings FOR SELECT USING (true);
CREATE POLICY "set_ins" ON store_settings FOR INSERT WITH CHECK (true);
CREATE POLICY "set_upd" ON store_settings FOR UPDATE USING (true);
CREATE POLICY "set_del" ON store_settings FOR DELETE USING (true);

-- Realtime (Safe Publication Add)
DO $$
BEGIN
  BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE orders; EXCEPTION WHEN duplicate_object THEN NULL; END;
  BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE order_items; EXCEPTION WHEN duplicate_object THEN NULL; END;
  BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE products; EXCEPTION WHEN duplicate_object THEN NULL; END;
  BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE customers; EXCEPTION WHEN duplicate_object THEN NULL; END;
  BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE stock_movements; EXCEPTION WHEN duplicate_object THEN NULL; END;
  BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE reviews; EXCEPTION WHEN duplicate_object THEN NULL; END;
END
$$;

-- RPC Function
CREATE OR REPLACE FUNCTION create_order_transaction(
  p_store_id UUID,
  p_customer_id UUID,
  p_order_number TEXT,
  p_subtotal NUMERIC,
  p_discount NUMERIC,
  p_tax NUMERIC,
  p_total NUMERIC,
  p_payment_method TEXT,
  p_note TEXT,
  p_created_by UUID,
  p_items JSONB
) RETURNS orders LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_order orders;
  v_item JSONB;
BEGIN
  VALUES (uuid_generate_v4(), p_store_id, p_customer_id, p_order_number, p_subtotal, p_discount, p_tax, p_total, p_payment_method, p_note, p_created_by)
  RETURNING * INTO v_order;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    VALUES (uuid_generate_v4(), v_order.id, (v_item->>'product_id')::UUID, v_item->>'product_name', (v_item->>'quantity')::INT, (v_item->>'unit_price')::NUMERIC, (v_item->>'total')::NUMERIC);

    UPDATE products SET stock = stock - (v_item->>'quantity')::INT, updated_at = NOW()
    WHERE id = (v_item->>'product_id')::UUID;

    VALUES (uuid_generate_v4(), p_store_id, (v_item->>'product_id')::UUID, 'out', (v_item->>'quantity')::INT, v_order.id, 'order', 'Order ' || p_order_number, p_created_by);
  END LOOP;

  IF p_customer_id IS NOT NULL THEN
    UPDATE customers SET total_orders = total_orders + 1, total_spending = total_spending + p_total, updated_at = NOW()
    WHERE id = p_customer_id;
  END IF;

  RETURN v_order;
END;
$$;

